//! Parity: `{{ Pipe() }}` templating and parameter resolution match Python's
//! `replace_pipes_syntax` / `Pipe.parameters` (`fixtures/templates.json`, generated by
//! `fixtures/gen_templates.py` with in-memory stub pipes).

mod common;

use meerschaum_core::Value;
use meerschaum_core::pipe::{Pipe, PipeDefaults};
use meerschaum_core::template::{
    InMemoryResolver, TemplateResolver, referenced_pipes, referenced_pipes_in_parameters,
    replace_pipes_syntax,
};

fn resolver(fixture: &Value) -> InMemoryResolver {
    let defaults = PipeDefaults {
        cache_enabled: false,
        ..PipeDefaults::default()
    };
    let pipes = fixture
        .get("registered")
        .and_then(Value::as_list)
        .unwrap()
        .iter()
        .map(|r| {
            let r = r.as_list().unwrap();
            let mut kwargs = meerschaum_core::Map::new();
            kwargs.insert("parameters".into(), r[3].clone());
            Pipe::from_call(&r[..3], &kwargs, &defaults).unwrap()
        })
        .collect();
    InMemoryResolver { defaults, pipes }
}

fn failures(warnings: &[String]) -> i64 {
    warnings
        .iter()
        .filter(|w| w.starts_with("Failed to resolve pipe syntax"))
        .count() as i64
}

#[test]
fn replace_pipes_syntax_matches_python() {
    let fixture = common::load_fixture("templates.json");
    let r = resolver(&fixture);
    for case in fixture.get("replace").and_then(Value::as_list).unwrap() {
        let text = case.get("text").and_then(Value::as_str).unwrap();
        let self_pipe = case.get("self").and_then(Value::as_list).map(|keys| {
            r.load_pipe(&Pipe::from_call(keys, &Default::default(), &r.defaults).unwrap())
        });
        let out = replace_pipes_syntax(text, self_pipe.as_ref(), &r);
        common::assert_same(&out.value, case.get("value").unwrap(), text);
        assert_eq!(
            failures(&out.warnings),
            case.get("failures").and_then(Value::as_i64).unwrap(),
            "failure count for {text:?}: {:?}",
            out.warnings
        );
    }
}

#[test]
fn resolved_parameters_match_python() {
    let fixture = common::load_fixture("templates.json");
    let r = resolver(&fixture);
    for case in fixture.get("resolve").and_then(Value::as_list).unwrap() {
        let keys = case.get("keys").and_then(Value::as_list).unwrap();
        let pipe = r.load_pipe(&Pipe::from_call(keys, &Default::default(), &r.defaults).unwrap());
        let out = pipe.resolved_parameters(&r, None).unwrap();
        let context = format!("{pipe}");
        common::assert_same(
            &Value::Map(out.parameters),
            case.get("parameters").unwrap(),
            &context,
        );
        assert_eq!(
            failures(&out.warnings),
            case.get("failures").and_then(Value::as_i64).unwrap(),
            "failure count for {context}: {:?}",
            out.warnings
        );
    }
}

#[test]
fn static_extraction_finds_every_reference() {
    let fixture = common::load_fixture("templates.json");
    let r = resolver(&fixture);
    let clone = r.pipes.iter().find(|p| p.metric_key() == "clone").unwrap();
    let refs = referenced_pipes_in_parameters(clone.parameters(), Some(clone), &r.defaults);
    assert_eq!(refs.len(), 1);
    assert_eq!(refs[0].to_string(), "Pipe('sql:main', 'src')");

    let sql = "SELECT * FROM {{ Pipe('sql:main', 'a') }} a JOIN {{ mrsm.Pipe('plugin:b', 'b', 'x', instance='sql:other').columns['id'] }} b JOIN {{ Pipe('bad') }}";
    let found = referenced_pipes(sql, None, &r.defaults);
    let names: Vec<String> = found.iter().map(|f| f.pipe.to_string()).collect();
    assert_eq!(
        names,
        vec![
            "Pipe('sql:main', 'a')".to_string(),
            "Pipe('plugin:b', 'b', 'x', instance='sql:other')".to_string()
        ]
    );
}
